#pragma once

#include <ap_int.h>
#include <hls_stream.h>
#include <hls_task.h>

// Completion is transported through registered FIFOs instead of the
// combinational ap_done/ap_continue network generated by control-driven
// DATAFLOW.  Pairing the four local completions also limits every physical
// completion hop to one neighbouring SLR in the U250 floorplan.
using int4_completion_token_t = ap_uint<1>;

template <int JOIN_ID>
static void int4_join_task_completion_pair(
    hls::stream<int4_completion_token_t>& first,
    hls::stream<int4_completion_token_t>& second,
    hls::stream<int4_completion_token_t>& joined) {
#pragma HLS INLINE off
    (void)first.read();
    (void)second.read();
    joined.write(1);
}

template <int WAIT_ID>
static void int4_wait_task_completion_pairs(
    hls::stream<int4_completion_token_t>& pair01,
    hls::stream<int4_completion_token_t>& pair23) {
#pragma HLS INLINE off
    (void)pair01.read();
    (void)pair23.read();
}
